import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { uv, vec3, mix, step, smoothstep, positionGeometry, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, ExtrudeGeometry, Shape, CircleGeometry, Color, Vector2 } = ctx.THREE;

  const group = new Group();

  // --- Dimensions ---
  const w = 2.6;
  const h = 0.68;
  const r = 0.08;
  const bevelDepth = 0.03;
  const bevelSegments = 3;

  // --- Rounded-rect shape ---
  const shape = new Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x + r, y);
  shape.lineTo(x + w - r, y);
  shape.quadraticCurveTo(x + w, y, x + w, y + r);
  shape.lineTo(x + w, y + h - r);
  shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  shape.lineTo(x + r, y + h);
  shape.quadraticCurveTo(x, y + h, x, y + h - r);
  shape.lineTo(x, y + r);
  shape.quadraticCurveTo(x, y, x + r, y);

  const extrudeSettings = {
    steps: 1,
    depth: bevelDepth,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.03,
    bevelSegments: bevelSegments,
  };
  const geometry = new ExtrudeGeometry(shape, extrudeSettings);
  geometry.center();

  // --- Gradient material ---
  const colorTop = new Color('#ff4450');
  const colorMid = new Color('#ff2a38');
  const colorBottom = new Color('#c1121f');

  const yNorm = float(1).sub(uv().y); // 0 at top, 1 at bottom
  const mix1 = smoothstep(0, 0.55, yNorm);
  const colorA = mix(colorTop, colorMid, mix1);
  const mix2 = smoothstep(0.55, 1, yNorm);
  const colorB = mix(colorMid, colorBottom, mix2);
  const gradColor = mix(colorA, colorB, step(0.55, yNorm));

  // Hard seam line at 50% (yNorm=0.5)
  const seamCenter = 0.5;
  const seamWidth = 0.01;
  const seamMask = step(yNorm, seamCenter + seamWidth / 2).mul(step(seamCenter - seamWidth / 2, yNorm));
  const seamColor = new Color(1, 1, 1);
  const finalColor = mix(gradColor, seamColor, seamMask);

  const material = new MeshStandardNodeMaterial();
  material.colorNode = vec3(finalColor);
  material.roughness = 0.5;
  material.metalness = 0.35;
  material.clearcoat = 0.22;

  const button = new Mesh(geometry, material);
  group.add(button);

  // --- Perimeter emissive border ---
  const inset = 0.015;
  const innerShape = new Shape();
  const ix = x + inset;
  const iy = y + inset;
  const iw = w - 2 * inset;
  const ih = h - 2 * inset;
  const ir = Math.max(0, r - inset);
  innerShape.moveTo(ix + ir, iy);
  innerShape.lineTo(ix + iw - ir, iy);
  innerShape.quadraticCurveTo(ix + iw, iy, ix + iw, iy + ir);
  innerShape.lineTo(ix + iw, iy + ih - ir);
  innerShape.quadraticCurveTo(ix + iw, iy + ih, ix + iw - ir, iy + ih);
  innerShape.lineTo(ix + ir, iy + ih);
  innerShape.quadraticCurveTo(ix, iy + ih, ix, iy + ih - ir);
  innerShape.lineTo(ix, iy + ir);
  innerShape.quadraticCurveTo(ix, iy, ix + ir, iy);

  const combinedShape = shape.clone();
  combinedShape.holes.push(innerShape);
  const borderGeometry = new ExtrudeGeometry(combinedShape, extrudeSettings);
  borderGeometry.center();

  const borderMaterial = new MeshStandardNodeMaterial();
  borderMaterial.color = new Color('#ff2a38');
  borderMaterial.emissive = new Color('#ff2a38');
  borderMaterial.emissiveIntensity = 1.6;
  borderMaterial.roughness = 0.5;
  borderMaterial.metalness = 0.35;

  const border = new Mesh(borderGeometry, borderMaterial);
  group.add(border);

  // --- Text ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let labelStr = 'BEGIN COMMISSION';
  let captionStr = 'NO DEPOSIT REQUIRED';
  items.forEach(item => {
    if (item.role === 'cta-label') labelStr = item.text;
    if (item.role === 'caption') captionStr = item.text;
  });

  const label = ctx.fontAtlas.createText(labelStr, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.08 * 20,
  });
  label.scale.set(0.015, 0.015, 0.015);
  label.position.set(0, 0, bevelDepth + 0.02);
  group.add(label);

  const caption = ctx.fontAtlas.createText(captionStr, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12 * 9,
  });
  caption.scale.copy(label.scale);
  caption.position.set(0, -h / 2 - 0.15, bevelDepth + 0.02);
  group.add(caption);

  // --- Contact shadow ---
  const shadowRadius = w * 1.2;
  const shadowGeo = new CircleGeometry(shadowRadius, 32);
  const shadowMat = new MeshBasicNodeMaterial();
  const dist = positionGeometry.distance(new Vector2(0, 0));
  const opacity = float(0.35).mul(float(1).sub(smoothstep(0, shadowRadius, dist)));
  shadowMat.opacityNode = opacity;
  shadowMat.color = new Color(0, 0, 0);
  shadowMat.transparent = true;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -bevelDepth - 0.05;
  group.add(shadow);

  // --- Entrance animation (weighted-settle) ---
  group.scale.set(1.04, 1.04, 1.04);
  const entranceTL = gsap.timeline();
  entranceTL.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });

  // --- Interaction handlers ---
  const tweens = [];
  const handlers = {
    hover: {
      in: () => {
        const t1 = gsap.to(button.position, { z: 0.06, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        const t2 = gsap.to(border.position, { z: 0.06, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        const t3 = gsap.to(borderMaterial, { emissiveIntensity: 2.2, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        tweens.push(t1, t2, t3);
      },
      out: () => {
        const t1 = gsap.to(button.position, { z: 0, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        const t2 = gsap.to(border.position, { z: 0, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        const t3 = gsap.to(borderMaterial, { emissiveIntensity: 1.6, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        tweens.push(t1, t2, t3);
      },
    },
    click: {
      down: () => {
        const t1 = gsap.to(group.scale, {
          x: 0.97, y: 0.97, z: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
        });
        const t2 = gsap.to(shadow.scale, {
          x: 0.9, y: 0.9, z: 0.9,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
        });
        tweens.push(t1, t2);
      },
      up: () => {
        const t1 = gsap.to(group.scale, {
          x: 1, y: 1, z: 1,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
        });
        const t2 = gsap.to(shadow.scale, {
          x: 1, y: 1, z: 1,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
        });
        tweens.push(t1, t2);
      },
    },
  };

  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    entranceTL.kill();
    tweens.forEach(t => t.kill());
    geometry.dispose();
    borderGeometry.dispose();
    shadowGeo.dispose();
    material.dispose();
    borderMaterial.dispose();
    shadowMat.dispose();
    // text objects are managed by fontAtlas, remove from scene
    if (label.parent) label.parent.remove(label);
    if (caption.parent) caption.parent.remove(caption);
  };

  return group;
}
